// 여기서 전체 앱이 백엔드 없이도 돌아가도록 가상 응답을 관리
import { buildKey } from "./mockUtil";

// "가상 DB"
const MOCK_DB = {
  // 판매거래처
  "/order/sellercustomer": [
    { cusNo: 1, cusComp: "판매처 A", cusName: "홍길동", cusEmail: "a@test.com", cusPhone: "010-1111-2222", cusAddr: "서울 강남구" },
    { cusNo: 2, cusComp: "판매처 B", cusName: "이몽룡", cusEmail: "b@test.com", cusPhone: "010-3333-4444", cusAddr: "부산 해운대구" },
  ],

  // 구매거래처
  "/buyer/buyercustomer": [
    { buyerNo: 1, buyerComp: "구매처 A", buyerName: "강감찬", buyerEmail: "aa@test.com", buyerPhone: "010-5555-1111", buyerAddr: "대전 유성구" },
    { buyerNo: 2, buyerComp: "구매처 B", buyerName: "을지문덕", buyerEmail: "bb@test.com", buyerPhone: "010-5555-2222", buyerAddr: "광주 북구" },
  ],

  // 상품리스트
  "/plan/itemlist": [
    { itemNo: 1, itemName: "완제품 A", itemCode: "ITEM-A", itemSpec: "규격A", itemPrice: 15000 },
    { itemNo: 2, itemName: "완제품 B", itemCode: "ITEM-B", itemSpec: "규격B", itemPrice: 20000 },
  ],

  // 부품리스트
  "/buyer/partlist": [
    { partNo: 1, partName: "부품 A", partCode: "PART-A", partSpec: "규격A", partPrice: 3000, buyerComp: "구매처 A" },
    { partNo: 2, partName: "부품 B", partCode: "PART-B", partSpec: "규격B", partPrice: 4500, buyerComp: "구매처 B" },
  ],

  // 부품발주
  "/buyer/partorder": [
    { poNo: 1, buyerComp: "구매처 A", partName: "부품 A", poQty: 50, poPrice: 3000, poState: "입고대기", poDate: "2025-10-01", buyerAddr: "대전 유성구" },
    { poNo: 2, buyerComp: "구매처 B", partName: "부품 B", poQty: 20, poPrice: 4500, poState: "입고대기", poDate: "2025-10-02", buyerAddr: "광주 북구" },
  ],

  // 상품주문
  "/order/list": [
    { orderNo: 1, cusComp: "판매처 A", itemName: "완제품 A", orderQty: 10, orderPrice: 15000, totalPrice: 150000, orderState: "승인대기", orderDeliState: "납품대기", orderDate: "2025-10-01", deliveryDate: "2025-10-05" },
    { orderNo: 2, cusComp: "판매처 B", itemName: "완제품 B", orderQty: 5, orderPrice: 20000, totalPrice: 100000, orderState: "승인대기", orderDeliState: "납품대기", orderDate: "2025-10-02", deliveryDate: "2025-10-06" },
  ],

  // BOM
  "/plan/bomlist": [
    { bomId: 1, itemName: "완제품 A", partName: "부품 A", qtyPerItem: 2 },
    { bomId: 2, itemName: "완제품 B", partName: "부품 B", qtyPerItem: 3 },
  ],

  // 생산계획
  "/plan/list": [
    { planNo: 1, itemName: "완제품 A", planName: "A-10월 생산", planQty: 100, planState: "생산중" },
    { planNo: 2, itemName: "완제품 B", planName: "B-10월 생산", planQty: 80, planState: "생산중" },
  ],
};


// 공통 응답기
function lookup(path, opts = {}) {
  const key = buildKey(path, opts);
  if (Object.prototype.hasOwnProperty.call(MOCK_DB, key)) {
    return structuredClone(MOCK_DB[key]);
  }

  console.warn("[mockBackend] no mock data for", key);
  // 기본값은 빈 배열로 돌려서 map() 호출하는 컴포넌트 에러 방지
  return [];
}

// 아래 함수들이 axios_api에서 호출
// axios_api는 { data: mockGet(...) } 형태로 래핑
// 순수 데이터만 반환
export function mockGet(path, opts = {}) {
  return lookup(path, opts);
}

export function mockPost(path, body, opts = {}) {
  console.log("[mockPost] pretend create:", path, body);
  return { success: true, message: "데모 모드: 등록완료." };
}

export function mockPut(path, body, opts = {}) {
  console.log("[mockPut] pretend update:", path, body);
  return { success: true, message: "데모 모드: 수정완료." };
}

export function mockDelete(path, opts = {}) {
  console.log("[mockDelete] pretend delete:", path);
  return { success: true, message: "데모 모드: 삭제완료." };
}
